const input = $input.first().json;

const localUrl = $env.LOCAL_AI_BASE_URL || 'http://host.docker.internal:18180/v1/chat/completions';
const localModel = $env.LOCAL_AI_MODEL || 'qwen3.5:4b';
const cloudUrl = $env.CLOUD_AI_BASE_URL || '';
const cloudModel = $env.CLOUD_AI_MODEL || '';
const cloudApiKey = $env.CLOUD_AI_API_KEY || '';

const prompt = input.prompt;
const maxTokens = Number(input.max_tokens || 256);
const policyName = input.policy_name || 'manual';

const localInputUsdPer1k = Number($env.LOCAL_AI_INPUT_USD_PER_1K || 0);
const localOutputUsdPer1k = Number($env.LOCAL_AI_OUTPUT_USD_PER_1K || 0);
const cloudInputUsdPer1k = Number($env.CLOUD_AI_INPUT_USD_PER_1K || 0);
const cloudOutputUsdPer1k = Number($env.CLOUD_AI_OUTPUT_USD_PER_1K || 0);

function buildBody(model) {
  return {
    model,
    temperature: 0.2,
    max_tokens: maxTokens,
    messages: [
      {
        role: 'system',
        content: `Use policy ${policyName}. Return concise Traditional Chinese content.`
      },
      {
        role: 'user',
        content: prompt
      }
    ]
  };
}

function usageOf(result) {
  const usage = result.usage || {};
  const promptTokens = Number(usage.prompt_tokens || usage.input_tokens || 0);
  const completionTokens = Number(usage.completion_tokens || usage.output_tokens || 0);
  const totalTokens = Number(usage.total_tokens || promptTokens + completionTokens || 0);
  return { promptTokens, completionTokens, totalTokens };
}

function estimateCost(usage, inRate, outRate) {
  return (usage.promptTokens / 1000) * inRate + (usage.completionTokens / 1000) * outRate;
}

async function callProvider(provider, url, model, apiKey, inRate, outRate) {
  if (!url || !model) {
    return {
      provider,
      skipped: true,
      error: 'missing url or model',
      latency_ms: null,
      prompt_tokens: 0,
      completion_tokens: 0,
      total_tokens: 0,
      estimated_cost_usd: 0
    };
  }

  const started = Date.now();
  try {
    const headers = { 'Content-Type': 'application/json' };
    if (apiKey) headers.Authorization = `Bearer ${apiKey}`;

    const result = await this.helpers.httpRequest({
      method: 'POST',
      url,
      headers,
      body: buildBody(model),
      json: true,
      timeout: 120000
    });

    const latencyMs = Date.now() - started;
    const usage = usageOf(result);
    const content = result.choices?.[0]?.message?.content || result.output_text || '';
    return {
      provider,
      skipped: false,
      model,
      latency_ms: latencyMs,
      prompt_tokens: usage.promptTokens,
      completion_tokens: usage.completionTokens,
      total_tokens: usage.totalTokens,
      estimated_cost_usd: estimateCost(usage, inRate, outRate),
      output_preview: String(content).slice(0, 300),
      raw_usage: result.usage || null
    };
  } catch (error) {
    return {
      provider,
      skipped: false,
      model,
      error: error.message,
      latency_ms: Date.now() - started,
      prompt_tokens: 0,
      completion_tokens: 0,
      total_tokens: 0,
      estimated_cost_usd: 0
    };
  }
}

const local = await callProvider.call(this, 'local', localUrl, localModel, '', localInputUsdPer1k, localOutputUsdPer1k);
const cloud = await callProvider.call(this, 'cloud', cloudUrl, cloudModel, cloudApiKey, cloudInputUsdPer1k, cloudOutputUsdPer1k);

const speedRatio = local.latency_ms && cloud.latency_ms ? cloud.latency_ms / local.latency_ms : null;
const costRatio = local.estimated_cost_usd > 0 ? cloud.estimated_cost_usd / local.estimated_cost_usd : null;

return [{
  json: {
    workflow: 'ai-provider-speed-cost-benchmark',
    policy_name: policyName,
    created_at: new Date().toISOString(),
    prompt_chars: prompt.length,
    max_tokens: maxTokens,
    local,
    cloud,
    speed_ratio_cloud_over_local: speedRatio,
    cost_ratio_cloud_over_local: costRatio,
    winner_speed: speedRatio === null ? 'unknown' : speedRatio > 1 ? 'local' : 'cloud',
    winner_cost: cloud.estimated_cost_usd === 0 && local.estimated_cost_usd === 0 ? 'unknown' : cloud.estimated_cost_usd > local.estimated_cost_usd ? 'local' : 'cloud'
  }
}];
